ON CONFLICT (slug) DO NOTHING;

SELECT s.id, n.num, NULL,
  to_jsonb(ARRAY[s.banner_url, s.cover_url, s.banner_url]),
  now() - (n.num || ' hours')::interval
FROM public.series s
CROSS JOIN (VALUES (1), (2), (3)) AS n(num)
WHERE s.slug IN ('chainsaw-man','na-honjaman-level-up','jujutsu-kaisen','berserk','one-piece','shingeki-no-kyojin')
ON CONFLICT (series_id, number) DO NOTHING;